-- Published starter curriculum. `content` is structured for future translations (en/mr/hi keys).
insert into public.modules(slug,title,description,icon,position,is_published) values
('productivity','Typing and Digital Productivity','Work confidently with devices, typing and files.','keyboard',1,true),
('sheets','Spreadsheet Skills','Organise information and calculate with confidence.','table',2,true),
('presentation','Presentation and Creativity','Communicate ideas clearly with slides.','presentation',3,true),
('safety','Cybersecurity and Digital Safety','Stay safe, private and alert online.','shield',4,true),
('coding','Coding and Logical Thinking','Break problems into clear steps.','code',5,true),
('research','Internet Research and AI Literacy','Search, check facts and use AI responsibly.','search',6,true)
on conflict(slug) do update set title=excluded.title,description=excluded.description,is_published=true;
insert into public.lessons(module_id,title,position,is_published,content)
select m.id,v.title,v.position,true,jsonb_build_object('en',jsonb_build_object('description',v.description,'objectives',v.objectives,'explanation',v.explanation,'activity',v.activity,'knowledgeCheck',v.check)) from public.modules m join (values
('productivity',1,'Computer basics','Identify common device parts and their jobs.','A computer takes input, processes it and shows output. Keyboard, mouse, monitor and storage each help with a task.','Label the input, output and storage parts of a computer you use.','Which device is used to type?'),
('productivity',2,'Keyboard and mouse basics','Use keys, clicks and scrolling accurately.','Keep wrists relaxed. Single click selects, double click opens, and right click shows choices.','Open a school folder and create one document.','What does double click usually do?'),
('productivity',3,'Typing accuracy and speed','Type accurately before trying to type quickly.','Use home-row fingers and look at the screen more than the keys. Accuracy avoids time-consuming corrections.','Type a five-line paragraph and correct every error.','Why is accuracy important?'),
('productivity',4,'Files and folders','Save and find school work safely.','A clear folder structure such as School > Class 9 > Science prevents lost work. Names should include topic and date.','Create folders for two subjects and save a sample file.','Which file name is easiest to find later?'),
('productivity',5,'Documents and shortcuts','Format a useful school document.','Headings, spacing and keyboard shortcuts make documents easier to read and edit. Ctrl+S saves your work.','Create a one-page notice using a heading and bullet points.','What does Ctrl+S do?'),
('sheets',1,'Introduction to spreadsheets','Recognise cells, sheets and workbooks.','A spreadsheet stores data in a grid. A workbook may contain several sheets.','Open a blank sheet and name it Marks.','What is a cell?'),
('sheets',2,'Rows, columns and cells','Use cell addresses to organise data.','Columns use letters and rows use numbers, so B3 means column B, row 3.','Enter names in A2:A5 and marks in B2:B5.','What does C4 mean?'),
('sheets',3,'Data entry and formatting','Make information readable.','Consistent headings, alignment and number formats help others understand a table quickly.','Format a marks table with a title and borders.','Why use a heading row?'),
('sheets',4,'Formulas and functions','Calculate totals and averages.','Formulas begin with =. SUM adds values, while AVERAGE finds their mean.','Calculate the average of three test scores.','Which symbol starts a formula?'),
('sheets',5,'Sorting and filtering','Find useful patterns in data.','Sorting changes order; filtering temporarily shows matching rows. Check that all columns move together.','Filter a list to show students scoring above 70.','What does filtering do?'),
('presentation',1,'Presentation basics','Plan slides for a clear audience.','A presentation is a visual guide, not a page of notes. One main idea per slide helps listeners.','Outline three slides for a local issue.','How many main ideas should a slide usually have?'),
('presentation',2,'Effective slides','Use short, readable slide text.','Large fonts and simple points are easier to read from the back of a classroom.','Turn a paragraph into three bullet points.','Why avoid long paragraphs?'),
('presentation',3,'Colour and typography','Choose accessible colours and fonts.','High contrast improves readability. Use one or two simple fonts throughout.','Check a slide for readable contrast.','What improves text readability?'),
('presentation',4,'Visual communication','Choose images that support an idea.','A useful image explains or illustrates a point and must be relevant and permitted to use.','Replace one decorative image with an informative chart.','What makes an image useful?'),
('presentation',5,'School presentation','Create a complete short presentation.','A strong talk has an opening, clear evidence and a conclusion. Practise aloud.','Make a three-slide presentation about saving water.','What belongs in a conclusion?'),
('safety',1,'Cybersecurity basics','Understand common online risks.','Cybersecurity protects devices, accounts and information from misuse.','List two things you should protect online.','What is cybersecurity?'),
('safety',2,'Passwords and 2FA','Make accounts harder to break into.','Use a long unique passphrase. Two-factor authentication adds a second check.','Create a memorable example passphrase, not your real password.','Should passwords be shared?'),
('safety',3,'Phishing and scams','Spot suspicious messages.','Scams create urgency and ask for passwords, codes or links. Verify through an official channel.','Mark three warning signs in a sample message.','What should you do with an unexpected OTP request?'),
('safety',4,'Privacy and social media','Control what you share.','Posts can be copied and forwarded. Avoid sharing address, passwords, location and private photos publicly.','Review privacy settings with a trusted adult.','Is an OTP safe to share?'),
('safety',5,'Safe internet habits','Use trustworthy sites and updates.','Updates fix security problems. Download only from official stores and ask for help when unsure.','Check whether a download page is official.','Why install updates?'),
('coding',1,'Programming ideas','Describe instructions precisely.','Programs are exact instructions. Breaking a task into small steps is called decomposition.','Write steps for making tea without skipping actions.','Why must instructions be clear?'),
('coding',2,'Variables and data','Store changing information.','A variable is a named place for a value, such as score = 10.','Name variables for a simple quiz score.','What can a variable store?'),
('coding',3,'Conditions','Make decisions in a program.','An if condition chooses an action when something is true, such as if marks >= 35.','Write a pass/fail rule in plain language.','What does an if statement do?'),
('coding',4,'Loops and logic','Repeat useful steps.','A loop repeats instructions and saves time. Ensure the loop has a clear stopping point.','Describe a loop that prints numbers 1 to 5.','Why use a loop?'),
('coding',5,'Web basics','Understand HTML, CSS and JavaScript roles.','HTML gives structure, CSS controls appearance, and JavaScript adds behaviour.','Identify the role of each technology on a webpage.','Which language styles a page?'),
('research',1,'Effective searching','Use keywords and search operators.','Good searches use specific words, dates and reliable domains rather than full questions.','Search for a recent government health notice.','What makes a search specific?'),
('research',2,'Reliable sources','Check author, evidence and date.','Prefer official institutions, known publications and sources that show evidence.','Compare an official website with an anonymous post.','Who published the information?'),
('research',3,'Fact checking','Verify before sharing.','Check the original source, date, context and independent reports before believing a claim.','Verify a viral claim using two reliable sources.','Why check the date?'),
('research',4,'Introduction to AI','Understand AI strengths and limits.','AI can find patterns and generate text, but it can be wrong or biased. People must check important answers.','Ask AI for study ideas then verify one fact.','Can AI make mistakes?'),
('research',5,'Responsible AI prompts','Ask clear and safe questions.','A strong prompt gives task, context, format and limits. Never put private information into a public tool.','Improve a vague prompt for a school poster.','What should never be included in a prompt?')
) as v(slug,position,title,description,objectives,explanation,activity,check) on v.slug=m.slug
on conflict(module_id,position) do update set title=excluded.title,content=excluded.content,is_published=true;
